mapper.select:
SELECT

FROM monthly_ticket_ledger
WHERE user_id = #{userId}
ORDER BY id DESC
LIMIT #{offset}, #{limit}

SELECT user_id
FROM monthly_ticket_lot
WHERE status = 'ACTIVE'
  AND remaining_amount > 0
  AND expire_at <= #{cutoff}
  AND user_id > #{afterUserId}
GROUP BY user_id
ORDER BY user_id ASC
LIMIT #{limit}

mapper.update:
UPDATE monthly_ticket_lot
SET remaining_amount = 0,
    status           = 'EXPIRED',
    closed_at        = #{closedAt},
    version          = version + 1
WHERE id = #{lotId}
  AND version = #{expectedVersion}
  AND status = 'ACTIVE'
  AND remaining_amount = #{expectedRemaining}
  AND expire_at <= #{closedAt}

UPDATE monthly_ticket_account
SET available_balance = available_balance - #{amount},
    lifetime_expired  = lifetime_expired + #{amount},
    version           = version + 1
WHERE id = #{accountId}
  AND version = #{expectedVersion}
  AND available_balance >= #{amount}

mapper.select:
SELECT COUNT(*)
FROM monthly_ticket_season
WHERE id = #{seasonId}
  AND status = 'OPEN'
  AND start_at <= #{at}
  AND vote_cutoff_at > #{at}

mapper.update:
UPDATE monthly_ticket_daily_counter
SET vote_count   = vote_count + 1,
    ticket_spent = ticket_spent + #{ticketCount},
    version      = version + 1
WHERE user_id = #{userId}
  AND local_date = #{localDate}
  AND vote_count < #{maxVotes}
  AND ticket_spent <= #{maxTickets} - #{ticketCount}

UPDATE monthly_ticket_user_book_quota
SET ticket_spent = ticket_spent + #{ticketCount},
    version      = version + 1
WHERE user_id = #{userId}
  AND season_id = #{seasonId}
  AND book_id = #{bookId}
  AND ticket_spent <= #{maxTickets} - #{ticketCount}

UPDATE monthly_ticket_lot
SET status = CASE WHEN remaining_amount = #{amount} THEN 'EXHAUSTED' ELSE 'ACTIVE' END,
    closed_at = CASE WHEN remaining_amount = #{amount} THEN #{at} ELSE NULL END,
    remaining_amount = remaining_amount - #{amount},
    version = version + 1
WHERE id = #{lotId}
  AND version = #{expectedVersion}
  AND status = 'ACTIVE'
  AND effective_at <= #{at}
  AND expire_at > #{at}
  AND remaining_amount >= #{amount}

UPDATE monthly_ticket_account
SET available_balance = available_balance - #{amount},
    lifetime_spent    = lifetime_spent + #{amount},
    version           = version + 1
WHERE id = #{accountId}
  AND version = #{expectedVersion}
  AND status = 'ACTIVE'
  AND available_balance >= #{amount}

mapper.select:
SELECT checkpoint
FROM scheduled_job_run
WHERE job_type = #{jobType}
  AND scope_type = #{scopeType}
  AND scope_key = #{scopeKey}
  AND status = 'RUNNING'
  AND owner_instance = #{ownerInstance}
LIMIT 1

mapper.update:
UPDATE scheduled_job_run
SET checkpoint      = #{checkpoint},
    processed_count = processed_count + #{processedDelta},
    heartbeat_at    = #{heartbeatAt},
    version         = version + 1
WHERE job_type = #{jobType}
  AND scope_type = #{scopeType}
  AND scope_key = #{scopeKey}
  AND status = 'RUNNING'
  AND owner_instance = #{ownerInstance}

UPDATE scheduled_job_run
SET status        = 'SUCCEEDED',
    heartbeat_at  = #{finishedAt},
    finished_at   = #{finishedAt},
    error_message = NULL,
    version       = version + 1
WHERE job_type = #{jobType}
  AND scope_type = #{scopeType}
  AND scope_key = #{scopeKey}
  AND status = 'RUNNING'
  AND owner_instance = #{ownerInstance}

UPDATE scheduled_job_run
SET status        = 'FAILED',
    heartbeat_at  = #{finishedAt},
    finished_at   = #{finishedAt},
    error_message = #{errorMessage},
    version       = version + 1
WHERE job_type = #{jobType}
  AND scope_type = #{scopeType}
  AND scope_key = #{scopeKey}
  AND status = 'RUNNING'
  AND owner_instance = #{ownerInstance}
